"""Faker SQL web app: renders the users generated by the faker.* stored procedures."""
from __future__ import annotations

import csv
import io
import math
import secrets
import time
from collections import Counter
from functools import lru_cache
from pathlib import Path

import markdown
import psycopg
from flask import Flask, Response, abort, redirect, render_template, request, url_for

from . import db

ROOT = Path(__file__).resolve().parents[1]
BATCH_SIZES = (10, 20, 50)
SEED_MIN, SEED_MAX = -(2 ** 63), 2 ** 63 - 1
MAP_W = 360.0
MAP_H = MAP_W / (math.pi * math.cos(math.radians(30)) ** 2)  # Behrmann, see tools/build_map.py

app = Flask(__name__)


# ----------------------------------------------------------------- helpers

@lru_cache(maxsize=1)
def locales_cached(epoch: int) -> tuple[tuple[str, str], ...]:
    del epoch  # only part of the cache key
    return tuple((r["code"], r["title"]) for r in db.list_locales())


def locales() -> tuple[tuple[str, str], ...]:
    # refreshed every 10 minutes, so a new locale shows up without a redeploy
    return locales_cached(int(time.time() // 600))


class Params:
    """Validated generator arguments from the query string."""

    def __init__(self, args):
        codes = [code for code, _ in locales()]
        self.errors: list[str] = []
        self.locale = args.get("locale", codes[0] if codes else "en_US")
        if self.locale not in codes:
            self.errors.append(f"Unknown locale “{self.locale}”. Choose one from the list.")
            self.locale = codes[0]
        raw_seed = (args.get("seed") or "").strip().replace("−", "-")
        try:
            self.seed = int(raw_seed)
            if not SEED_MIN <= self.seed <= SEED_MAX:
                raise ValueError
        except ValueError:
            self.seed = None
            if raw_seed:
                self.errors.append("The seed must be a whole number between −9 223 372 036 854 775 808 "
                                   "and 9 223 372 036 854 775 807.")
        try:
            self.size = int(args.get("size", BATCH_SIZES[0]))
        except ValueError:
            self.size = BATCH_SIZES[0]
        if self.size not in BATCH_SIZES:
            self.size = BATCH_SIZES[0]
        try:
            self.batch = max(1, min(int(args.get("batch", 1)), 10_000_000))
        except ValueError:
            self.batch = 1
        # the checkbox sends "1"; a form without it is "text off", a bare URL is "text on"
        self.text = args.get("text", "1" if "seed" not in args else "0") == "1"

    def query(self, **override) -> dict:
        q = {"locale": self.locale, "seed": self.seed, "size": self.size,
             "batch": self.batch, "text": "1" if self.text else "0"}
        q.update(override)
        return q


def map_point(lat: float, lon: float) -> tuple[float, float]:
    return round(lon + 180.0, 2), round(MAP_H / 2 - math.sin(math.radians(lat)) * MAP_H / 2, 2)


def decorate(users: list[dict]) -> list[dict]:
    for u in users:
        u["map_x"], u["map_y"] = map_point(u["latitude"], u["longitude"])
    return users


@app.template_filter("thousands")
def thousands(value) -> str:
    return f"{int(value):,}".replace(",", " ")


@app.context_processor
def globals_():
    return {"nav": [("index", "Generator"), ("distribution", "Distribution"),
                    ("benchmark", "Benchmark"), ("docs", "Docs")],
            "map_h": MAP_H, "repo_url": "https://github.com/GammaSphere/itransition-task6-faker-sql"}


@app.errorhandler(psycopg.Error)
def database_error(err):
    return render_template("error.html", message=str(err).strip().splitlines()[0]), 503


# ----------------------------------------------------------------- generator

@app.get("/")
def index():
    params = Params(request.args)
    if params.seed is None and not params.errors:
        return redirect(url_for("index", **params.query(seed=secrets.randbelow(10 ** 8))))
    if request.args.get("random"):
        return redirect(url_for("index", **params.query(seed=secrets.randbelow(10 ** 8), batch=1)))
    users = []
    if params.seed is not None:
        users = decorate(db.generate_users(params.locale, params.seed, params.batch - 1, params.size, params.text))
    return render_template("index.html", p=params, users=users, locales=locales(), sizes=BATCH_SIZES)


@app.get("/batch")
def batch():
    """One batch as table rows; the page appends it when "Load next batch" is pressed."""
    params = Params(request.args)
    if params.seed is None or params.errors:
        abort(400)
    users = decorate(db.generate_users(params.locale, params.seed, params.batch - 1, params.size, params.text))
    return render_template("_batch.html", p=params, users=users)


@app.get("/api/users")
def api_users():
    params = Params(request.args)
    if params.seed is None or params.errors:
        return {"errors": params.errors or ["seed is required"]}, 400
    users = db.generate_users(params.locale, params.seed, params.batch - 1, params.size, params.text)
    for u in users:
        for key in ("height_cm", "weight_kg"):
            u[key] = float(u[key])
    return {"locale": params.locale, "seed": params.seed, "batch": params.batch, "users": users}


@app.get("/export.csv")
def export_csv():
    params = Params(request.args)
    if params.seed is None or params.errors:
        abort(400)
    try:
        last = max(params.batch, min(int(request.args.get("to", params.batch)), params.batch + 99))
    except ValueError:
        last = params.batch
    users = []
    for number in range(params.batch, last + 1):
        users += db.generate_users(params.locale, params.seed, number - 1, params.size, params.text)
    out = io.StringIO()
    fields = ["pos", "full_name", "gender", "address", "latitude", "longitude", "height_cm", "weight_kg",
              "eye_color", "hair_color", "blood_type", "phone", "email", "about"]
    writer = csv.DictWriter(out, fieldnames=fields, extrasaction="ignore")
    writer.writeheader()
    for u in users:
        writer.writerow({**u, "pos": u["pos"] + 1})
    name = f"faker_{params.locale}_{params.seed}_batches_{params.batch}-{last}.csv"
    return Response(out.getvalue(), mimetype="text/csv",
                    headers={"Content-Disposition": f'attachment; filename="{name}"'})


# ----------------------------------------------------------------- distribution

def histogram(values, lo, hi, bins):
    counts = [0] * bins
    for v in values:
        if lo <= v < hi:
            counts[int((v - lo) / (hi - lo) * bins)] += 1
    return counts


def normal_pdf(x, mean, sd):
    return math.exp(-0.5 * ((x - mean) / sd) ** 2) / (sd * math.sqrt(2 * math.pi))


@app.get("/distribution")
def distribution():
    params = Params(request.args)
    seed = params.seed if params.seed is not None else 2024
    n = 4000
    rows = db.sample(params.locale, seed, n)
    points = [map_point(r["latitude"], r["longitude"]) for r in rows]

    # latitude: 18 bands of 10°, expected share = (sin(b) - sin(a)) / 2
    lat_counts = histogram([r["latitude"] for r in rows], -90, 90, 18)
    lat_bands = []
    for i, c in enumerate(lat_counts):
        a, b = math.radians(-90 + 10 * i), math.radians(-80 + 10 * i)
        lat_bands.append({"from": -90 + 10 * i, "count": c, "expected": n * (math.sin(b) - math.sin(a)) / 2,
                          "naive": n / 18})

    stats = db.body_stats(params.locale)
    heights = []
    for gender in ("F", "M"):
        values = [float(r["height_cm"]) for r in rows if r["gender"] == gender]
        st = stats[gender]
        counts = histogram(values, 130, 220, 45)
        heights.append({
            "gender": gender, "n": len(values),
            "mean": sum(values) / len(values),
            "sd": math.sqrt(sum((v - sum(values) / len(values)) ** 2 for v in values) / len(values)),
            "target_mean": st["height_mean_cm"], "target_sd": st["height_sd_cm"],
            "counts": counts,
            "curve": [len(values) * 2 * normal_pdf(130 + 2 * i + 1, st["height_mean_cm"], st["height_sd_cm"])
                      for i in range(45)],
        })

    eye_counts = Counter(r["eye_color"] for r in rows)
    weights = db.word_weights(params.locale, "eye_color")
    total_w = sum(w["weight"] for w in weights)
    eyes = [{"value": w["value"], "share": eye_counts[w["value"]] / n, "expected": w["weight"] / total_w}
            for w in weights]
    return render_template("distribution.html", p=params, seed=seed, n=n, points=points, lat_bands=lat_bands,
                           heights=heights, eyes=eyes, locales=locales())


# ----------------------------------------------------------------- benchmark & docs

@app.get("/benchmark")
def benchmark():
    params = Params(request.args)
    result = None
    if request.args.get("run"):
        users = 2000 if params.text else 5000
        result = db.benchmark(params.locale, users, params.text)
    return render_template("benchmark.html", p=params, result=result, locales=locales(),
                           report=load_report())


@lru_cache(maxsize=1)
def load_report() -> str:
    path = ROOT / "docs" / "BENCHMARK.md"
    return markdown.markdown(path.read_text(encoding="utf-8"), extensions=["tables"]) if path.exists() else ""


@lru_cache(maxsize=1)
def docs_html() -> tuple[str, str]:
    md = markdown.Markdown(extensions=["tables", "fenced_code", "toc"],
                           extension_configs={"toc": {"toc_depth": "2-3"}})
    html = md.convert((ROOT / "docs" / "FAKER_SQL.md").read_text(encoding="utf-8"))
    return html, md.toc  # type: ignore[attr-defined]


@app.get("/docs")
def docs():
    html, toc = docs_html()
    return render_template("docs.html", content=html, toc=toc, sizes=db.lookup_sizes())


@app.get("/healthz")
def healthz():
    return {"ok": True, "locales": [c for c, _ in locales()]}
